implements(Key) :-
    citation(Key, _).

citation(eu_reg_2025_2518_art_4_1, [label - 'Regulation (EU) 2025/2518 Art 4(1), admissibility of a complaint concerning cross-border processing', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_004.001)', verbatim - 'A complaint on the basis of Regulation (EU) 2016/679 concerning cross-border processing shall be admissible provided that it includes the following information:']).
citation(eu_reg_2025_2518_art_4_1_a, [label - 'Regulation (EU) 2025/2518 Art 4(1), first subparagraph, point (a), name and contact details of the person lodging the complaint', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_004.001_a)', verbatim - 'the name and contact details of the person lodging the complaint']).
citation(eu_reg_2025_2518_art_4_1_b, [label - 'Regulation (EU) 2025/2518 Art 4(1), first subparagraph, point (b), proof of proper constitution of an Article 80 body', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_004.001_b)', verbatim - 'proof that that body, organisation or association has been properly constituted in accordance with the law of a Member State']).
citation(eu_reg_2025_2518_art_4_1_c, [label - 'Regulation (EU) 2025/2518 Art 4(1), first subparagraph, point (c), proof of a mandate of a data subject for an Article 80(1) body', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_004.001_c)', verbatim - 'proof that that body, organisation or association is acting on the basis of a mandate of a data subject']).
citation(eu_reg_2025_2518_art_4_1_d, [label - 'Regulation (EU) 2025/2518 Art 4(1), first subparagraph, point (d), information identifying the controller or processor', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_004.001_d)', verbatim - 'information which facilitates the identification of the controller or processor that is the subject of the complaint']).
citation(eu_reg_2025_2518_art_4_1_e, [label - 'Regulation (EU) 2025/2518 Art 4(1), first subparagraph, point (e), description of the alleged infringement', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_004.001_e)', verbatim - 'a description of the alleged infringement of Regulation (EU) 2016/679']).
citation(eu_reg_2025_2518_art_4_2, [label - 'Regulation (EU) 2025/2518 Art 4(2), declaration of inadmissibility within two weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_004.002)', verbatim - 'it shall, within two weeks of receiving that complaint, declare that complaint inadmissible and inform the complainant of the reasons thereof']).
citation(eu_reg_2025_2518_art_4_3, [label - 'Regulation (EU) 2025/2518 Art 4(3), prior request to the controller', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_004.003)', verbatim - 'that request shall be made to the controller before that complaint is lodged']).
citation(eu_reg_2025_2518_art_4_5, [label - 'Regulation (EU) 2025/2518 Art 4(5), transmission within six weeks and binding determination of admissibility', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_004.005)', verbatim - 'shall transmit that complaint to the supervisory authority it presumes is competent to act as lead supervisory authority no later than six weeks from the receipt of that complaint']).
citation(eu_reg_2025_2518_art_4_6, [label - 'Regulation (EU) 2025/2518 Art 4(6), confirmation of competence or referral to the Board within six weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_004.006)', verbatim - 'Within six weeks of the receipt of a complaint, the supervisory authority presumed to be competent to act as lead supervisory authority shall either confirm its competence or']).
citation(eu_reg_2025_2518_art_5_1, [label - 'Regulation (EU) 2025/2518 Art 5(1), early resolution of a complaint concerning Chapter III rights', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_005.001)', verbatim - 'which concerns the exercise of the rights of the data subject under Chapter III of Regulation (EU) 2016/679 may, where appropriate, be resolved through a procedure allowing for its early resolution by']).
citation(eu_reg_2025_2518_art_5_1_a, [label - 'Regulation (EU) 2025/2518 Art 5(1), first subparagraph, point (a), early resolution by the authority with which the complaint was lodged', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_005.001_a)', verbatim - 'the supervisory authority with which the complaint has been lodged, after it has determined by way of preliminary conclusion that the complaint concerns cross-border processing']).
citation(eu_reg_2025_2518_art_5_1_b, [label - 'Regulation (EU) 2025/2518 Art 5(1), first subparagraph, point (b), early resolution by the lead supervisory authority', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_005.001_b)', verbatim - 'the lead supervisory authority to which the complaint has been transmitted, at any time before the submission of the preliminary findings']).
citation(eu_reg_2025_2518_art_5_2, [label - 'Regulation (EU) 2025/2518 Art 5(2), opening words, complaint devoid of purpose', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_005.002)', verbatim - 'establishes, based on supporting evidence, that the alleged infringement has been brought to an end, that supervisory authority shall consider the complaint devoid of purpose']).
citation(eu_reg_2025_2518_art_5_2_c, [label - 'Regulation (EU) 2025/2518 Art 5(2), second subparagraph, point (c), objection to the early resolution within four weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_005.002_c)', verbatim - 'of the possibility for the complainant to submit an objection to the early resolution within four weeks of receiving such information']).
citation(eu_reg_2025_2518_art_5_3, [label - 'Regulation (EU) 2025/2518 Art 5(3), resolution established by the authority with which the complaint was lodged within two weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_005.003)', verbatim - 'that supervisory authority shall, within two weeks of the expiry of that time limit, establish that the complaint has been resolved']).
citation(eu_reg_2025_2518_art_5_4, [label - 'Regulation (EU) 2025/2518 Art 5(4), draft decision establishing resolution by the lead authority within four weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_005.004)', verbatim - 'that lead supervisory authority shall submit a draft decision in accordance with Article 60(3) of Regulation (EU) 2016/679 within four weeks of the expiry of that time limit']).
citation(eu_reg_2025_2518_art_5_6, [label - 'Regulation (EU) 2025/2518 Art 5(6), Articles 10 to 20 do not apply to complaints resolved early', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_005.006)', verbatim - 'Articles 10 to 20 do not apply to complaints resolved pursuant to this Article.']).
citation(eu_reg_2025_2518_art_6_1, [label - 'Regulation (EU) 2025/2518 Art 6(1), simple cooperation procedure', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_006.001)', verbatim - 'it may cooperate with the other supervisory authorities concerned through a simple cooperation procedure']).
citation(eu_reg_2025_2518_art_6_1_a, [label - 'Regulation (EU) 2025/2518 Art 6(1), first subparagraph, point (a), no reasonable doubt as to the scope of the investigation', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_006.001_a)', verbatim - 'it considers that no reasonable doubt exists as to the scope of the investigation']).
citation(eu_reg_2025_2518_art_6_1_b, [label - 'Regulation (EU) 2025/2518 Art 6(1), first subparagraph, point (b), issues not requiring the additional cooperation of a complex investigation', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#point_006.001_b)', verbatim - 'the legal and factual issues identified by the lead supervisory authority do not require the additional cooperation with the other supervisory authorities concerned that would be required for the purposes of a complex investigation']).
citation(eu_reg_2025_2518_art_6_2, [label - 'Regulation (EU) 2025/2518 Art 6(2), notification of the simple cooperation procedure within six weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_006.002)', verbatim - 'within six weeks of the lead supervisory authority confirming its competence pursuant to Article 4(6) of this Regulation']).
citation(eu_reg_2025_2518_art_6_3, [label - 'Regulation (EU) 2025/2518 Art 6(3), objection to the simple cooperation procedure within two weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_006.003)', verbatim - 'Where any of the other supervisory authorities concerned object to the application of the simple cooperation procedure within two weeks of being notified thereof, that procedure shall not apply']).
citation(eu_reg_2025_2518_art_6_5, [label - 'Regulation (EU) 2025/2518 Art 6(5), Chapter III does not apply to cases handled under Article 56(2) of Regulation (EU) 2016/679', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_006.005)', verbatim - 'Chapter III does not apply to cases handled by the supervisory authority concerned pursuant to Article 56(2) of Regulation (EU) 2016/679.']).
citation(eu_reg_2025_2518_art_10_3, [label - 'Regulation (EU) 2025/2518 Art 10(3), summary of key issues within three months', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_010.003)', verbatim - 'within three months of the lead supervisory authority confirming its competence pursuant to Article 4(6) of this Regulation']).
citation(eu_reg_2025_2518_art_10_4, [label - 'Regulation (EU) 2025/2518 Art 10(4), comments on the summary of key issues within four weeks, extendable by two weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_010.004)', verbatim - 'The supervisory authorities concerned may provide comments on the summary of key issues within four weeks of receipt of that summary. The lead supervisory authority may extend that period by two weeks']).
citation(eu_reg_2025_2518_art_10_5, [label - 'Regulation (EU) 2025/2518 Art 10(5), response to comments within four weeks, extendable by two weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_010.005)', verbatim - 'The lead supervisory authority shall respond to those comments within four weeks of the expiry of the period referred to in paragraph 4']).
citation(eu_reg_2025_2518_art_12_1, [label - 'Regulation (EU) 2025/2518 Art 12(1), draft decision within 15 months', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_012.001)', verbatim - 'The lead supervisory authority shall submit a draft decision pursuant to Article 60(3) of Regulation (EU) 2016/679 within 15 months of the lead supervisory authority confirming its competence']).
citation(eu_reg_2025_2518_art_12_2, [label - 'Regulation (EU) 2025/2518 Art 12(2), suspension of the time limit after a request under Article 11(6)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_012.002)', verbatim - 'the time limit referred to in paragraph 1 of this Article shall be suspended until the Board has adopted its binding decision']).
citation(eu_reg_2025_2518_art_12_3, [label - 'Regulation (EU) 2025/2518 Art 12(3), exceptional extension by no longer than 12 months', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_012.003)', verbatim - 'the lead supervisory authority may extend the time limit referred to in paragraph 1 once, for a period of no longer than 12 months, due to the complexity of the case']).
citation(eu_reg_2025_2518_art_12_4, [label - 'Regulation (EU) 2025/2518 Art 12(4), objection to the extension within two weeks', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_012.004)', verbatim - 'Any supervisory authority concerned may submit an objection to the extension of the time limit within two weeks of being informed thereof pursuant to paragraph 3.']).
citation(eu_reg_2025_2518_art_12_6, [label - 'Regulation (EU) 2025/2518 Art 12(6), draft decision within 12 months under the simple cooperation procedure', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_012.006)', verbatim - 'the lead supervisory authority shall submit a draft decision pursuant to Article 60(3) of Regulation (EU) 2016/679 within 12 months of the lead supervisory authority confirming its competence']).
citation(eu_reg_2025_2518_art_14, [label - 'Regulation (EU) 2025/2518 Art 14, legality and validity of procedural steps taken after a time limit', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#art_014)', verbatim - 'taking such a step after the expiry of that time limit shall not affect the legality or validity of that procedural step or of the final decision']).
citation(eu_reg_2025_2518_art_36, [label - 'Regulation (EU) 2025/2518 Art 36, transitional provisions for Chapters III to VI', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#art_036)', verbatim - 'Chapters III and IV shall apply to ex officio investigations opened after 2 April 2027 and to complaint-based investigations where the complaint was lodged after 2 April 2027.']).
citation(eu_reg_2025_2518_art_37_2, [label - 'Regulation (EU) 2025/2518 Art 37(2), date of application', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#parag_037.002)', verbatim - 'This Regulation shall apply from 2 April 2027.']).
