citation(time_limit_source_statement, [label - 'Referral target: attested classification of the provision that set the missed time limit (read by Regulation (EU) 2025/2518 Art 14)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32025R2518 (unit 32025R2518#art_014; source provision not pinned)']).
